import React, { useState, useEffect } from 'react';
import LandingPage from './components/LandingPage.tsx';
import FlowerCard from './components/FlowerCard.tsx';
import { getFlowerRecommendations } from './services/geminiService.ts';
import { Flower, ViewState } from './types.ts';
import { Loader2, RefreshCw, Leaf, X, Download } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('LANDING');
  const [flowers, setFlowers] = useState<Flower[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [currentQuery, setCurrentQuery] = useState<string>('');
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallClick = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') setDeferredPrompt(null);
  };

  const handleStart = async (query: string = '') => {
    let formattedQuery = query.trim();
    if (/^\d{1,2}$/.test(formattedQuery)) {
      formattedQuery = `${formattedQuery}월`;
    }
    setView('LOADING');
    setError(null);
    setCurrentQuery(formattedQuery);
    try {
      const data = await getFlowerRecommendations(formattedQuery);
      setFlowers(data);
      setView('RESULTS');
    } catch (err) {
      setError("죄송합니다. 꽃 정보를 불러오는데 실패했습니다.");
      setView('ERROR');
    }
  };

  const handleReset = () => {
    setView('LANDING');
    setFlowers([]);
    setCurrentQuery('');
  };

  const handleRetry = () => handleStart(currentQuery);

  return (
    <div className="min-h-screen bg-stone-50 font-sans text-stone-900 selection:bg-emerald-200">
      {view === 'LANDING' && (
        <LandingPage 
          onStart={handleStart} 
          onInstall={handleInstallClick}
          canInstall={!!deferredPrompt}
        />
      )}

      {view === 'LOADING' && (
        <div className="flex flex-col items-center justify-center min-h-screen text-center px-4">
          <Loader2 className="w-16 h-16 text-emerald-600 animate-spin" />
          <h2 className="mt-8 text-2xl font-serif text-stone-800">추천 정보를 찾고 있습니다...</h2>
        </div>
      )}

      {view === 'ERROR' && (
        <div className="flex flex-col items-center justify-center min-h-screen px-4 text-center">
          <Leaf className="w-16 h-16 text-red-400 mb-6" />
          <h2 className="text-2xl font-bold mb-8">{error}</h2>
          <button onClick={handleRetry} className="px-6 py-3 bg-stone-900 text-white rounded-lg flex items-center gap-2">
            <RefreshCw size={18} /> 다시 시도
          </button>
        </div>
      )}

      {view === 'RESULTS' && (
        <div className="min-h-screen bg-stone-50">
          <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-stone-100 p-4">
            <div className="max-w-5xl mx-auto flex justify-between items-center">
              <div className="flex items-center gap-2 font-serif font-bold text-xl"><Leaf className="text-emerald-600"/> 뭐 심지?</div>
              <button onClick={handleReset} className="p-2 text-stone-400 hover:text-stone-900"><X size={24}/></button>
            </div>
          </header>
          <main className="max-w-5xl mx-auto px-6 py-12">
            <div className="text-center mb-12">
              <h2 className="text-4xl font-serif text-stone-900 mb-4">{currentQuery || '이달의'} 추천 꽃 TOP 10</h2>
            </div>
            <div className="grid gap-8 grid-cols-1 md:grid-cols-2">
              {flowers.map((flower) => <FlowerCard key={flower.rank} flower={flower} />)}
            </div>
          </main>
        </div>
      )}
    </div>
  );
};

export default App;

